CREATE TABLE assessments (
    id UUID PRIMARY KEY, title VARCHAR(180) NOT NULL, description VARCHAR(1000) NOT NULL,
    assessment_type VARCHAR(30) NOT NULL, target_role VARCHAR(160), difficulty VARCHAR(20) NOT NULL,
    duration_minutes INTEGER NOT NULL CHECK (duration_minutes > 0), total_questions INTEGER NOT NULL CHECK (total_questions > 0),
    passing_percentage INTEGER NOT NULL CHECK (passing_percentage BETWEEN 0 AND 100), generation_source VARCHAR(30) NOT NULL,
    generation_model VARCHAR(120), created_by UUID REFERENCES users(id) ON DELETE SET NULL, active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL
);
CREATE TABLE assessment_questions (
    id UUID PRIMARY KEY, assessment_id UUID NOT NULL REFERENCES assessments(id) ON DELETE CASCADE,
    question_order INTEGER NOT NULL, question_type VARCHAR(30) NOT NULL, question_text VARCHAR(1000) NOT NULL,
    explanation VARCHAR(1500), difficulty VARCHAR(20) NOT NULL, skill_tag VARCHAR(120), created_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT uk_assessment_question_order UNIQUE (assessment_id, question_order)
);
CREATE TABLE assessment_options (
    id UUID PRIMARY KEY, question_id UUID NOT NULL REFERENCES assessment_questions(id) ON DELETE CASCADE,
    option_key VARCHAR(10) NOT NULL, option_text VARCHAR(500) NOT NULL, is_correct BOOLEAN NOT NULL, created_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT uk_assessment_option_key UNIQUE (question_id, option_key)
);
CREATE TABLE assessment_attempts (
    id UUID PRIMARY KEY, assessment_id UUID NOT NULL REFERENCES assessments(id) ON DELETE RESTRICT,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, status VARCHAR(20) NOT NULL,
    started_at TIMESTAMPTZ NOT NULL, submitted_at TIMESTAMPTZ, score_percentage INTEGER CHECK (score_percentage BETWEEN 0 AND 100),
    correct_answers INTEGER NOT NULL DEFAULT 0, incorrect_answers INTEGER NOT NULL DEFAULT 0, unanswered INTEGER NOT NULL DEFAULT 0,
    total_questions INTEGER NOT NULL, duration_seconds INTEGER, created_at TIMESTAMPTZ NOT NULL
);
CREATE INDEX idx_assessment_attempt_history ON assessment_attempts(user_id, created_at DESC);
CREATE TABLE assessment_answers (
    id UUID PRIMARY KEY, attempt_id UUID NOT NULL REFERENCES assessment_attempts(id) ON DELETE CASCADE,
    question_id UUID NOT NULL REFERENCES assessment_questions(id) ON DELETE RESTRICT,
    selected_option_key VARCHAR(10), text_answer VARCHAR(2000), is_correct BOOLEAN, awarded_points NUMERIC(6,2) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL, CONSTRAINT uk_attempt_question_answer UNIQUE (attempt_id, question_id)
);

